with flattened as (select id, customer_id, created_at, tag from carts lateral view outer explode(coupon_codes) x as tag), with_dims as (select a.*, d.segment, d.email from flattened a join customers d on a.customer_id = d.id), valid as (select *, substring(segment, 1, 4) as segment_prefix, length(email) as email_length from with_dims where created_at > to_date('2025-03-01')) select created_at, tag, email, segment_prefix, email_length from valid
